create table public.stores (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, name text not null, created_at timestamptz not null default now(), unique(company_id,name));`ncreate index stores_company_idx on public.stores(company_id);`nalter table public.stores enable row level security;`ncreate policy stores_member_read on public.stores for select using (public.is_company_member(company_id));